#!/usr/bin/env bash
set -euo pipefail

cmd=${1:-list}
shift || true

case "$cmd" in
  list)   pass ls ;;
  get)    pass show -c{{clipboard_seconds}} "$1" ;;
  add)    pass insert -m "$1" ;;
  search) pass grep "$1" ;;
  gen)    pass generate "$1" "${2:-20}" ;;
  rm)     pass rm "$1" ;;
  *) echo "usage: $0 {list|get|add|search|gen|rm} <name>"; exit 1 ;;
esac
